select energy_manager.load_cards($cards$[
{"id":"p4-b02-033","paper":4,"topic":"Furnace Performance","kind":"problem","front":"Find the radiation heat loss through a 1 m x 1 m furnace opening that is open for the whole balancing period, with the furnace at 1340 °C, wall 0.46 m thick, and ambient 40 °C. Use shape coefficient 0.70 and furnace temperature 1613 K.","back":"Radiation loss through openings = 38,485 kcal per tonne of billet.","explain":"Openings are a large radiation loss because the fourth-power temperature law acts on the full furnace temperature. Thick walls and square profiles reduce the coefficient, so the example uses 0.70.","flash":false,"source":"BEE Book 4 Ch 02 p57","steps":[{"prompt":"Find the coefficient from the opening profile.","answer":"Shape: square; shortest side / wall thickness = 1 / 0.46 = 2.17; coefficient Phi = 0.70 (book, from Table I)","explain":"Thick walls reduce radiation through an opening, so the ratio matters."},{"prompt":"Compute the radiation loss per hour per tonne of billet.","answer":"1 x 1 x 0.70 x 4.88 x [(1613/100)^4 - (313/100)^4] / 6 = 38,485 kcal/t","explain":"Open time is 1 hour; area is 1 m2; furnace temperature is in Kelvin (1613 K) and base temperature 313 K."}],"order":4153},
{"id":"p4-b02-034","paper":4,"topic":"Furnace Performance","kind":"problem","front":"For the oil-fired furnace example, find the unaccounted losses per tonne of billet and the total heat output, with heat input 6,15,140 kcal/t.","back":"Unaccounted losses = 13,945 kcal/t (2.3%). Total heat output = 6,15,140 kcal/t.","explain":"Unaccounted losses are what remains between total input and the sum of all measured outputs. The 2.3% is the share of input that the measured losses do not explain.","flash":false,"source":"BEE Book 4 Ch 02 p58","steps":[{"prompt":"Add the total heat input.","answer":"Total input = 6,13,300 + 1,840 = 6,15,140 kcal/t","explain":"Total input is the sum of combustion and sensible heat of the fuel."},{"prompt":"Add all measured heat outputs.","answer":"1,56,000 + 3,22,247 + 58,042 + 20,070 + 229 + 6,122 + 38,485 = 6,01,195 kcal/t","explain":"Outputs are the billet load, dry flue gas, water vapour from H2, moisture in air, CO, body loss and openings."},{"prompt":"Find the unaccounted losses.","answer":"6,15,140 - 6,01,195 = 13,945 kcal/t (2.3% of input)","explain":"The book writes this as (Q1 + Q2) - (Q3 + Q4 + Q5 + Q6 + Q7 + Q8 + Q9)."}],"order":4154},
{"id":"p4-b02-035","paper":4,"topic":"Furnace Performance","kind":"problem","front":"At 1700 °C vs 700 °C, how many times greater is radiation from an open furnace door (using absolute temperatures)?","back":"About 16.9 times.","explain":"The ratio follows the fourth-power law: (T1 / T2)^4 with both in Kelvin. The book's table gives 11.02 for 1500 °C, which the same formula reproduces.","flash":false,"source":"BEE Book 4 Ch 02 p59","steps":[{"prompt":"Convert both temperatures to Kelvin.","answer":"1700 C = 1973 K; 700 C = 973 K","explain":"Radiation law uses absolute temperature, so add 273 to each Celsius value."},{"prompt":"Compute the ratio of fourth powers.","answer":"(1973 / 973)^4 = (2.0277)^4 = 16.9","explain":"The ratio is 16.9 times the radiation at 700 C."}],"order":4155},
{"id":"p4-b02-036","paper":4,"topic":"Furnace Performance","kind":"problem","front":"A reheating furnace burns 6,500 kg/day of fuel (65 per tonne of 100 t/day) with flue gas O2 8%, flue gas at 600 °C, ambient 30 °C. A recuperator preheats the combustion air from 30 °C to 200 °C (theoretical air 14 kg/kg fuel; Cp flue gas 0.26, Cp air 0.24). What percentage of heat in the flue gas is recovered by the recuperator?","back":"26.4% of heat in flue gas is recovered.","explain":"The recuperator recovers heat that would leave the stack, so the percentage is the heat in preheated air divided by heat in the flue gas. The book takes excess air from O2 first, then the heat values per day.","flash":false,"source":"BEE Book 4 Ch 02 p63","steps":[{"prompt":"Find excess air and actual air supplied.","answer":"EA = 8 / (21 - 8) x 100 = 61.5%; AAS = (1 + 0.615) x 14 = 22.61 kg air/kg fuel","explain":"Theoretical air is 14 kg/kg fuel. Excess air uses the O2 formula."},{"prompt":"Find the heat in the flue gas per day.","answer":"(6500 + 6500 x 22.61) x 0.26 x (600 - 30) = 2,27,43,513 kcal/day","explain":"Flue gas mass = fuel plus air per day; specific heat 0.26; temperature drop 600 to 30 C."},{"prompt":"Find the heat in the preheated air per day.","answer":"6500 x 22.61 x 0.24 x (200 - 30) = 59,96,172 kcal/day","explain":"This is the heat returned to the furnace by the recuperator."},{"prompt":"Find the % heat reduction in flue gas.","answer":"59,96,172 / 2,27,43,513 = 26.4%","explain":"Heat recovered is about a quarter of the flue gas heat."}],"order":4156},
{"id":"p4-b02-037","paper":4,"topic":"Furnace Performance","kind":"problem","front":"With the recuperator, yield rises from 90% to 95% on the same fuel, so daily production rises from 100 t/day. What is the new daily production and the extra output?","back":"105.5 t/day; extra output of 5.5 t/day.","explain":"Yield improvement scales production by the ratio of new to old yield. The book uses the same fuel to give more billet output.","flash":false,"source":"BEE Book 4 Ch 02 p63","steps":[{"prompt":"Compute production at the new yield.","answer":"100 x 95 / 90 = 105.5 t/day","explain":"Same fuel input, higher yield, so output scales with the yield ratio."},{"prompt":"Find the extra production.","answer":"105.5 - 100 = 5.5 t/day","explain":"This is the daily gain from the yield improvement alone."}],"order":4157},
{"id":"p4-b02-038","paper":4,"topic":"Furnace Performance","kind":"problem","front":"After the recuperator (1% fuel saved per 20 °C rise in air temperature, air rising from 30 to 200 °C), with 6500 kg/day of fuel and 105.5 t/day of production, find the new fuel use and specific fuel consumption.","back":"Fuel saving = 8.5%; fuel = 5,947.5 kg/day; specific fuel consumption = 56.37 kg/t.","explain":"The book takes 65 per tonne as kg, giving 6500 kg/day from 100 t/day. Its SFC calculation divides the new daily fuel by the new production, not the old.","flash":false,"source":"BEE Book 4 Ch 02 p63","steps":[{"prompt":"Find the fuel saving.","answer":"(200 - 30) / 20 = 8.5%","explain":"Rule of thumb from the question: 1% fuel saved for each 20 C rise in combustion air temperature."},{"prompt":"Find the new daily fuel consumption.","answer":"6500 - (6500 x 0.085) = 5,947.5 kg/day","explain":"Apply the saving to the original daily fuel."},{"prompt":"Find the new specific fuel consumption.","answer":"5,947.5 / 105.5 = 56.37 kg/tonne","explain":"SFC is fuel per tonne of production; production rises with yield, so SFC falls."}],"order":4158},
{"id":"p4-b02-039","paper":4,"topic":"Furnace Performance","kind":"problem","front":"Find the partial specific heat of CO2 in dry flue gas at 655 °C, given CO2 mass fraction 0.096 and CO2 specific heat 0.4995 kcal/Nm3 °C.","back":"Partial specific heat = 0.0244 kcal/kg °C.","explain":"Each gas contributes a partial value. The sum of all partial values gives the dry flue gas specific heat of 0.26 kcal/kg °C.","flash":false,"source":"BEE Book 4 Ch 02 p62","steps":[{"prompt":"Write the partial specific heat formula.","answer":"Partial Cp = mass fraction x specific heat x 22.4 / molecular weight","explain":"The 22.4 m3 per kmol factor converts from volume-based specific heat to mass-based."},{"prompt":"Substitute CO2 values.","answer":"0.096 x 0.4995 x 22.4 / 44 = 0.0244 kcal/kg °C","explain":"Molecular weight of CO2 is 44; mass fraction 0.096 comes from 3.15 kg CO2 / 32.86 kg dry flue gas."}],"order":4159},
{"id":"p4-b03-001","paper":4,"topic":"Cogeneration Performance","kind":"fact","front":"What are the three broad classes of cogeneration system the chapter lists?","back":"Steam turbine systems, gas turbine systems and DG (diesel generator) sets.","explain":"Gas turbine systems usually pair with a heat recovery steam generator (HRSG) to make steam. The performance assessment method depends on which class the plant belongs to.","flash":true,"source":"BEE Book 4 Ch 03 p67","order":4160},
{"id":"p4-b03-002","paper":4,"topic":"Cogeneration Performance","kind":"fact","front":"Which steam turbine configurations does the chapter list for cogeneration?","back":"Extraction, back-pressure, or a combination of back-pressure, extraction and condensing.","explain":"The mode of power generation sets how steam is split between the process and the turbine. Because power and steam loads vary, the whole system is dynamic and needs a performance assessment.","flash":false,"source":"BEE Book 4 Ch 03 p67","order":4161},
{"id":"p4-b03-003","paper":4,"topic":"Cogeneration Performance","kind":"fact","front":"How does a gas turbine cogeneration system recover heat?","back":"Exhaust gas from the gas turbine passes through a heat recovery steam generator (HRSG) that raises steam.","explain":"The HRSG is the heat recovery link in gas turbine cogeneration. Its thermal efficiency is one of the parameters a performance test checks.","flash":false,"source":"BEE Book 4 Ch 03 p67","order":4162},
{"id":"p4-b03-004","paper":4,"topic":"Cogeneration Performance","kind":"fact","front":"What is the main purpose of a cogeneration plant performance test?","back":"To determine the power output and the plant heat rate.","explain":"Some tests also check one component, such as the steam turbine, where deterioration is suspected. Other tests show maintenance results after a major overhaul or evaluate a full plant revamp.","flash":false,"source":"BEE Book 4 Ch 03 p67","order":4163},
{"id":"p4-b03-005","paper":4,"topic":"Cogeneration Performance","kind":"fact","front":"Against what should a cogeneration plant's test result be compared?","back":"Baseline values for the plant's actual operating condition, not design values.","explain":"Baseline values match how the plant really runs, so they show deterioration fairly. Design values describe conditions the plant may not operate at.","flash":true,"source":"BEE Book 4 Ch 03 p67","order":4164},
{"id":"p4-b03-006","paper":4,"topic":"Cogeneration Performance","kind":"fact","front":"What are the units of overall plant fuel rate?","back":"kg/kWh for solid or liquid fuel, or Sm³/kWh for gas.","explain":"It is fuel consumption (kg/h or Sm³/h) divided by power output (kW). A lower fuel rate means less fuel per unit of power.","flash":true,"source":"BEE Book 4 Ch 03 p67","order":4165},
{"id":"p4-b03-007","paper":4,"topic":"Steam Turbine Performance","kind":"fact","front":"What is the formula for turbine stage (isentropic) efficiency?","back":"Actual enthalpy drop across the stage ÷ isentropic (ideal) enthalpy drop across the stage × 100, in %.","explain":"The isentropic drop is the ideal expansion from the same inlet state to the same exit pressure at constant entropy. It is read from a Mollier (h-s) chart.","flash":false,"source":"BEE Book 4 Ch 03 p68","order":4166},
{"id":"p4-b03-008","paper":4,"topic":"Steam Turbine Performance","kind":"fact","front":"How is overall plant heat rate calculated for a steam turbine cogeneration plant?","back":"Overall plant fuel rate (kg/kWh) × GCV of the fuel (kcal/kg), giving kcal/kWh.","explain":"Heat rate is the heat input needed per kWh of power output. It is a plant-level measure, so it covers boiler and turbine losses together.","flash":true,"source":"BEE Book 4 Ch 03 p68","order":4167},
{"id":"p4-b03-009","paper":4,"topic":"Gas Turbine and HRSG","kind":"fact","front":"How is overall plant heat rate calculated for a gas turbine plant?","back":"Overall plant fuel rate (Sm³/kWh) × NCV of the gas (kcal/Sm³).","explain":"The chapter formula uses the NCV (net or lower calorific value) basis. The worked example labels its 9465 kcal/Sm³ figure as the lower heating value, which is the same basis.","flash":false,"source":"BEE Book 4 Ch 03 p68","order":4168},
{"id":"p4-b03-010","paper":4,"topic":"Gas Turbine and HRSG","kind":"fact","front":"What is the formula for HRSG thermal efficiency?","back":"η = steam flow × (steam enthalpy − feed water enthalpy) × 100 ÷ [(exhaust gas flow × inlet gas enthalpy) + (auxiliary fuel × GCV)].","explain":"Inlet gas enthalpy is the heat content of the exhaust at inlet temperature, taken as Cp × inlet temperature. The auxiliary fuel term is zero when no supplementary fuel is fired.","flash":false,"source":"BEE Book 4 Ch 03 p68","order":4169},
{"id":"p4-b03-011","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"Which reference standard does the chapter cite for cogeneration performance tests?","back":"ASME performance test codes.","explain":"The test procedure is then set for each plant separately, based on its configuration, instruments and operating conditions.","flash":true,"source":"BEE Book 4 Ch 03 p68","order":4170},
{"id":"p4-b03-012","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"How long should a cogeneration test run in a continuous process industry?","back":"About 8 hours of data gives reasonably reliable results.","explain":"The chapter says test duration is site specific. For plants with fluctuating electrical or steam loads, take a 24-hour set of samples over a representative period.","flash":false,"source":"BEE Book 4 Ch 03 p68","order":4171},
{"id":"p4-b03-013","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"Which instruments does the chapter suggest for flue gas oxygen and unburnt losses?","back":"A zirconium probe oxygen analyser for flue gas; gravimetric analysis for unburnt material.","explain":"The oxygen reading is needed for combustion and excess air calculations. Unburnt material is measured by weighing it, not by an online meter.","flash":false,"source":"BEE Book 4 Ch 03 p68","order":4172},
{"id":"p4-b03-014","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"Which meters does the chapter suggest for steam, fuel and air or flue gas flow?","back":"Steam: orifice flow meter. Fuel: volumetric or mass flow meter. Air or flue gas: venturi, orifice or pitot tubes.","explain":"These are the flow measurements that feed the steam and fuel side of the heat and energy balance. Match the meter to the stream, since a pitot tube suits gas and an orifice suits steam.","flash":false,"source":"BEE Book 4 Ch 03 p68","order":4173},
{"id":"p4-b03-015","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"Which instruments does the chapter suggest for cooling water, pressure, power and condensate?","back":"Cooling water: orifice, weir, channel or non-contact flow meter. Pressure: Bourdon gauge. Power: trivector or energy meter. Condensate: orifice flow meter.","explain":"Power is read from a trivector or energy meter, so electrical output is measured directly rather than estimated. Pressure is measured with Bourdon gauges.","flash":false,"source":"BEE Book 4 Ch 03 p69","order":4174},
{"id":"p4-b03-016","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"When must cogeneration test data be collected?","back":"During steady-state plant running conditions.","explain":"Readings taken while loads are changing do not show the plant's true performance. Confirm steady state before recording the data.","flash":true,"source":"BEE Book 4 Ch 03 p69","order":4175},
{"id":"p4-b03-017","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"What thermal data does the chapter list for a cogeneration test?","back":"Flow, pressure and temperature at: turbine steam inlet, fuel input to boiler or gas turbine, combustion air, extraction steam to process, back-pressure steam, condensing steam, condensate, turbine bypass steam, flue gas to HRSG, exit flue gas with composition, and cooling water to the condenser.","explain":"These points cover every stream that enters or leaves the cycle. Missing one of them makes the heat balance impossible to close.","flash":false,"source":"BEE Book 4 Ch 03 p69","order":4176},
{"id":"p4-b03-018","paper":4,"topic":"Cogeneration Test Procedure","kind":"fact","front":"What electrical data should a cogeneration test collect?","back":"Total power generated by each turbine over the trial, hourly average generation, power imported from the grid, and auxiliary power consumption.","explain":"Grid import and auxiliary consumption are needed to find the net power the plant delivers. Hourly averages help show how stable the output was.","flash":false,"source":"BEE Book 4 Ch 03 p69","order":4177},
{"id":"p4-b03-019","paper":4,"topic":"Steam Turbine Performance","kind":"fact","front":"What dryness value can estimate the heat drop in the last (condensing) stage?","back":"Typical dryness of 0.88 to 0.92, used as a first approximation.","explain":"Steam in the condensing stage is wet, so its enthalpy cannot be taken as saturated steam. The chapter prefers working out the last-stage efficiency from overall turbine efficiency and the other stage efficiencies.","flash":true,"source":"BEE Book 4 Ch 03 p71","order":4178},
{"id":"p4-b03-020","paper":4,"topic":"Steam Turbine Performance","kind":"fact","front":"Why is a vertical line drawn on the Mollier chart from the turbine inlet point?","back":"Expansion through a turbine is adiabatic, so entropy stays constant. The vertical (constant entropy) line reads the ideal exit enthalpy at each pressure.","explain":"Following the vertical line from inlet to extraction pressure gives the ideal enthalpy H2. The same line from the extraction point down to condenser pressure gives H3 (isentropic).","flash":false,"source":"BEE Book 4 Ch 03 p71","order":4179},
{"id":"p4-b03-021","paper":4,"topic":"Steam Turbine Performance","kind":"fact","front":"What is the formula for generator power output from turbine output?","back":"Pg (MW) = Pt × η mechanical × η gearbox × η generator, with the efficiencies in %.","explain":"Each drive-train stage takes a share of the shaft power, so the efficiencies multiply. Pt is the turbine output in MW.","flash":false,"source":"BEE Book 4 Ch 03 p72","order":4180},
{"id":"p4-b03-022","paper":4,"topic":"Steam Turbine Performance","kind":"fact","front":"What is the chapter's turbine power formula in terms of steam flow and enthalpy?","back":"Power (MW) = sum of [steam flow (kg/h) × enthalpy drop (kcal/kg)] ÷ (860 × 1000), one term per stage.","explain":"860 kcal is equal to 1 kWh, so dividing kcal/h by 860 gives kW. The book's printed formula is partly garbled in the OCR, so this reading follows the worked examples.","flash":false,"source":"BEE Book 4 Ch 03 p72","order":4181},
{"id":"p4-b03-023","paper":4,"topic":"Steam Turbine Performance","kind":"problem","front":"A back-pressure turbine takes 25 TPH of steam at 800 kcal/kg and exhausts it at 650 kcal/kg. What is its power output in MW?","back":"About 4.36 MW (3,750,000 kcal/h ÷ 860 = 4,360 kW).","explain":"Power comes from steam flow times enthalpy drop, divided by 860 kcal per kWh. These numbers are illustrative and are not from the book.","flash":false,"source":"BEE Book 4 Ch 03 p72","steps":[{"prompt":"Convert the steam flow to kg/h.","answer":"25 TPH = 25,000 kg/h","explain":"The chapter formula uses kg/h for flow."},{"prompt":"Find the enthalpy drop across the turbine.","answer":"800 − 650 = 150 kcal/kg","explain":"Enthalpy drop is inlet enthalpy minus exit enthalpy."},{"prompt":"Find the heat converted per hour.","answer":"25,000 × 150 = 3,750,000 kcal/h","explain":"Flow times enthalpy drop gives the heat converted per hour."},{"prompt":"Convert to kW and then MW.","answer":"3,750,000 ÷ 860 = 4,360 kW = 4.36 MW","explain":"860 kcal = 1 kWh."}],"order":4182},
{"id":"p4-b03-024","paper":4,"topic":"Steam Turbine Performance","kind":"problem","front":"A turbine delivers 4.36 MW at its shaft. Mechanical efficiency is 98%, gearbox 97% and generator 96%. What is the generator output?","back":"About 3.98 MW (4.36 × 0.98 × 0.97 × 0.96).","explain":"The three efficiencies multiply, because each drive-train stage takes its own share of the shaft power. The efficiency values here are illustrative, not from the book.","flash":false,"source":"BEE Book 4 Ch 03 p72","steps":[{"prompt":"Identify the turbine output.","answer":"4.36 MW","explain":"Shaft power from the turbine calculation."},{"prompt":"Multiply the three efficiencies.","answer":"0.98 × 0.97 × 0.96 = 0.9126","explain":"Losses compound across the mechanical, gear and generator stages."},{"prompt":"Apply the combined efficiency to the turbine output.","answer":"4.36 × 0.9126 = 3.98 MW","explain":"Generator output is turbine output times the combined efficiency."}],"order":4183},
{"id":"p4-b03-025","paper":4,"topic":"Steam Turbine Performance","kind":"problem","front":"Example 3.6.1: an extraction-condensing turbine has inlet enthalpy 807.9 kcal/kg, extraction actual 719.9 and isentropic 684.2 kcal/kg, and condensing actual 561 and isentropic 534.2 kcal/kg. Find the isentropic efficiency of the extraction stage and of the condensing stage.","back":"Extraction stage 71.14%; condensing stage 85.57%.","explain":"Each stage efficiency is actual drop divided by isentropic drop. The condensing stage works in wet steam, so its figure is an approximation.","flash":false,"source":"BEE Book 4 Ch 03 p73","steps":[{"prompt":"Find the actual drop to extraction.","answer":"807.9 − 719.9 = 88 kcal/kg","explain":"The actual drop runs from turbine inlet to extraction."},{"prompt":"Find the isentropic drop to extraction.","answer":"807.9 − 684.2 = 123.7 kcal/kg","explain":"The ideal drop comes from the Mollier chart for the same pressure change."},{"prompt":"Compute the extraction stage efficiency.","answer":"88 ÷ 123.7 × 100 = 71.14%","explain":"Ratio of actual to isentropic drop."},{"prompt":"Compute the condensing stage efficiency.","answer":"(719.9 − 561) ÷ (719.9 − 534.2) × 100 = 158.9 ÷ 185.7 = 85.57%","explain":"The same method, applied from the extraction condition down to the condenser."}],"order":4184},
{"id":"p4-b03-026","paper":4,"topic":"Steam Turbine Performance","kind":"problem","front":"Example 3.6.1 again: the extraction stage passes 19.2 TPH and the condensing stage 11.2 TPH, with the enthalpy values above. What is the power from each stage and the total?","back":"Book prints 1944 kW (extraction) + 2069.4 kW (condensing) = 4013 kW. Recalculating gives about 1965 kW for extraction and about 4034 kW in total.","explain":"Stage power is stage steam flow times enthalpy drop, divided by 860. The book's extraction figure does not match its own inputs, so check it before relying on it.","flash":false,"source":"BEE Book 4 Ch 03 p73","steps":[{"prompt":"Find the extraction stage enthalpy drop.","answer":"807.9 − 719.9 = 88 kcal/kg","explain":"Actual drop from inlet to extraction."},{"prompt":"Find the extraction stage power.","answer":"19,200 × 88 ÷ 860 = 1,965 kW (book prints 1944 kW)","explain":"Flow in kg/h times kcal/kg, divided by 860, gives kW. The book figure looks like a typo."},{"prompt":"Find the condensing stage power.","answer":"(719.9 − 561) = 158.9 kcal/kg; 11,200 × 158.9 ÷ 860 = 2,069.4 kW","explain":"The condensing stage uses the condenser flow of 11.2 TPH."},{"prompt":"Add the two stages.","answer":"1,965 + 2,069 ≈ 4,034 kW (book prints 4,013 kW)","explain":"The total moves with the extraction figure, so the book total is about 20 kW lower than its own inputs give."}],"order":4185},
{"id":"p4-b03-027","paper":4,"topic":"Cement Waste Heat Recovery","kind":"fact","front":"What kiln exit gas temperatures does the chapter give for 4-stage and for 5- to 6-stage preheaters?","back":"About 300-400 °C for a 4-stage preheater; 200-300 °C for a 5- or 6-stage preheater.","explain":"More preheater stages cool the kiln gas further before it leaves. Less heat is then left for a waste heat boiler, so the recovery potential depends on the stage count.","flash":false,"source":"BEE Book 4 Ch 03 p75","order":4186},
{"id":"p4-b03-028","paper":4,"topic":"Cement Waste Heat Recovery","kind":"fact","front":"What happens to clinker leaving the rotary kiln, and what heat does the cooler air carry?","back":"Clinker at about 1000 °C is cooled to 100-120 °C by ambient air. The hot air (200-300 °C) carries about 80-130 kcal/kg of clinker.","explain":"Part of the hot air is used as combustion air in the kiln. The rest is exhausted to the atmosphere unless a waste heat boiler recovers it.","flash":false,"source":"BEE Book 4 Ch 03 p76","order":4187},
{"id":"p4-b03-029","paper":4,"topic":"Cement Waste Heat Recovery","kind":"fact","front":"What are the main equipment items in a cement waste heat recovery power system?","back":"Suspension preheater (SP) boiler, air quenching chamber (AQC) boiler, steam turbine generator, distributed control system (DCS), water circulation system and dust-removal system.","explain":"The SP boiler and AQC boiler take heat from the preheater gas and the clinker cooler gas. Together they supply steam to the turbine generator.","flash":false,"source":"BEE Book 4 Ch 03 p76","order":4188},
{"id":"p4-b03-030","paper":4,"topic":"Cement Waste Heat Recovery","kind":"fact","front":"What decides the outlet temperature of flue gas leaving a cement waste heat boiler?","back":"Process requirements, such as the gas needed to dry raw material. Seasonal changes in drying demand must also be met in the design.","explain":"The outlet temperature sets how much heat can be recovered. A design that cools the gas too far may leave the drying process short of heat in some seasons.","flash":false,"source":"BEE Book 4 Ch 03 p76","order":4189},
{"id":"p4-b03-031","paper":4,"topic":"Gas Turbine Cogeneration","kind":"problem","front":"Gas turbine test: natural gas use is 1312 Sm³/h and average electrical output is 3994.5 kW. What is the overall plant fuel rate?","back":"0.3284 Sm³/kWh (1312 ÷ 3994.5).","explain":"This fuel rate is the basis for the heat rate and the EUF. Divide fuel consumption by power output over the same test period.","flash":false,"source":"BEE Book 4 Ch 03 p74","steps":[{"prompt":"Identify the fuel consumption.","answer":"1312 Sm³/h","explain":"Fuel flow from the test data."},{"prompt":"Identify the power output.","answer":"3994.5 kW","explain":"Average generator output during the test."},{"prompt":"Divide fuel by power.","answer":"1312 ÷ 3994.5 = 0.32844 Sm³/kWh","explain":"The units reduce to Sm³ per kWh."}],"order":4190},
{"id":"p4-b03-032","paper":4,"topic":"Gas Turbine Cogeneration","kind":"problem","front":"Same gas turbine test: fuel rate 0.32844 Sm³/kWh and gas NCV 9465 kcal/Sm³. What is the overall plant heat rate?","back":"About 3109 kcal/kWh (0.32844 × 9465).","explain":"Heat rate turns fuel rate into heat per kWh, so plants on different fuels can be compared. The chapter formula calls for the NCV basis.","flash":false,"source":"BEE Book 4 Ch 03 p75","steps":[{"prompt":"Identify the inputs.","answer":"Fuel rate 0.32844 Sm³/kWh; NCV of gas 9465 kcal/Sm³","explain":"Fuel rate comes from the previous step of the same test."},{"prompt":"Write the formula.","answer":"Heat rate = fuel rate (Sm³/kWh) × NCV of gas (kcal/Sm³)","explain":"This is the chapter formula for gas turbine plants."},{"prompt":"Multiply.","answer":"0.32844 × 9465 = 3108.7, about 3109 kcal/kWh","explain":"The result is the heat input per kWh of power."}],"order":4191},
{"id":"p4-b03-033","paper":4,"topic":"Gas Turbine Cogeneration","kind":"problem","front":"Same gas turbine test: WHRB steam flow 9145 kg/h, steam enthalpy 678.4 kcal/kg, feed water enthalpy 105 kcal/kg. Exhaust flow 14.32 kg/s at 542 °C, Cp 0.25 kcal/kg°C, no auxiliary fuel. What is the HRSG thermal efficiency by the book's method?","back":"About 75% (the book's answer).","explain":"The book's denominator uses the gas inlet heat content (flow × Cp × 542 °C) with no auxiliary fuel. Using the gas temperature drop (542 to 131.4 °C) instead gives about 99%, so use the book's method for the exam.","flash":false,"source":"BEE Book 4 Ch 03 p75","steps":[{"prompt":"Find the heat gained by the steam.","answer":"9145 × (678.4 − 105) = 5,243,743 kcal/h","explain":"Heat taken up by the feed water and steam per hour."},{"prompt":"Convert the exhaust flow to kg/h.","answer":"14.32 × 3600 ≈ 51,550 kg/h","explain":"Flow is given in kg/s."},{"prompt":"Find the gas heat term.","answer":"51,550 × 0.25 × 542 ≈ 6,985,000 kcal/h","explain":"Book's inlet gas enthalpy basis, with no auxiliary fuel term."},{"prompt":"Divide to get efficiency.","answer":"5,243,743 ÷ 6,985,000 × 100 ≈ 75%","explain":"Matches the book's answer."}],"order":4192},
{"id":"p4-b03-034","paper":4,"topic":"Gas Turbine Cogeneration","kind":"problem","front":"Same gas turbine test: electrical output 3994.5 kW, steam heat from 9145 kg/h × (678.4 − 105) kcal/kg, fuel 1312 Sm³/h at 9465 kcal/Sm³. What is the Energy Utilisation Factor (EUF)?","back":"About 70%.","explain":"EUF counts electrical output and useful steam heat together against the fuel heat input, so it rates a cogeneration plant better than power output alone. The book's example gives about 70%.","flash":false,"source":"BEE Book 4 Ch 03 p75","steps":[{"prompt":"Convert the electrical output to kcal/h.","answer":"3994.5 kW × 860 = 3,435,270 kcal/h","explain":"1 kWh = 860 kcal."},{"prompt":"Find the useful steam heat.","answer":"9145 × (678.4 − 105) = 5,243,743 kcal/h","explain":"Heat delivered to the steam per hour."},{"prompt":"Find the fuel heat input.","answer":"1312 × 9465 = 12,418,080 kcal/h","explain":"Fuel flow times NCV."},{"prompt":"Compute the EUF.","answer":"(3,435,270 + 5,243,743) ÷ 12,418,080 = 0.699, about 70%","explain":"Sum of useful outputs divided by fuel heat input."}],"order":4193}
]$cards$::jsonb);
